"""Source RNG is generated by R, not approximated in Python. Synthetic only."""
import hashlib
import json
import pathlib
import shutil
import subprocess
import sys

HERE = pathlib.Path(__file__).resolve().parent


def prepare(destination, rscript=None):
    out = pathlib.Path(destination)
    if out.is_symlink() or (out.exists() and (not out.is_dir() or any(out.iterdir()))):
        raise FileExistsError("fresh empty fixture directory required; preserve failures")
    rscript = rscript or shutil.which("Rscript")
    if not rscript:
        raise RuntimeError("OS_DEPENDENCY_MISSING: native R source RNG has not run")
    out.mkdir(parents=True, exist_ok=True)
    (out / "contract.json").write_bytes((HERE / "longitudinal_contract.json").read_bytes())
    command = [rscript, str(HERE / "make_longitudinal_inputs.R"), str(out.resolve())]
    with (out / "fixture.log").open("w") as stream:
        result = subprocess.run(command, stdout=stream, stderr=subprocess.STDOUT)
    if result.returncode:
        raise RuntimeError("R source fixture failed; preserve " + str(out))
    manifest = {"synthetic_contract_only": True, "owner_dataset": False, "source_case": "LONG-balanced-cells",
                "source_seed": 151, "source_commit": "12292d020ef4a8575a3a1db880b81786ee3547fa",
                "categorical_label_adaptation": "visits 1,2,3 -> visit1,visit2,visit3; original y RNG and order retained",
                "command": command, "files": {}}
    for name in ("longitudinal.csv", "reordered.csv", "contract.json", "fixture.log"):
        data = (out / name).read_bytes()
        manifest["files"][name] = {"sha256": hashlib.sha256(data).hexdigest(), "bytes": len(data)}
    (out / "SOURCE.json").write_text(json.dumps(manifest, indent=2) + "\n")
    return manifest


if __name__ == "__main__":
    prepare(sys.argv[1])
